const tasksWithProjects: TaskWithProject[] = [];
for (const project of searchProjects) {
  try {
    const data = await api.getProjectData(project.id);
    if (data.tasks) {
      for (const task of data.tasks) {
        tasksWithProjects.push({
          ...task,
          projectName: projectMap.get(task.projectId) || task.projectId,
        });
      }
    }
  } catch {
    continue;
  }
}

export interface TickTickConfig {
  clientId: string;
  clientSecret: string;
  accessToken?: string;
  refreshToken?: string;
  tokenExpiry?: number;
  redirectUri?: string;
}

export async function saveConfig(config: TickTickConfig): Promise<void> {
  await ensureConfigDir();
  await writeFile(CONFIG_FILE, JSON.stringify(config, null, 2), { mode: 0o600 });
  await chmod(CONFIG_DIR, 0o700).catch(() => {});
  await chmod(CONFIG_FILE, 0o600).catch(() => {});
}
